export type LayerName = 'surface' | 'parks' | 'water' | 'roads';

export interface RoadProperties {
  id: number;
  name?: string;
  highway?: string;
  road_length?: number;
  [key: string]: unknown;
}

export interface AreaProperties {
  id: number;
  name?: string;
  [key: string]: unknown;
}

export type RoadCollection = FeatureCollection<LineString, RoadProperties>;
